1	#!/usr/bin/env bun
2	/**
3	 * report_config_findings.ts — open an issue for a defect atoma found in the tools
4	 * file it was handed, and put an agent on it.
5	 *
6	 * ## What it reads
7	 *
8	 * `atoma` checks the tools file before it starts any server, and writes one
9	 * machine-readable line per defect to the run log:
10	 *
11	 *     ATOMA_CONFIG_FINDING: kind=dead_guard severity=warn server=web pattern=webhooks tools=fetch,hooks
12	 *     ATOMA_CONFIG_FINDING: kind=duplicate_tool severity=error tool=read servers=files,files_ro
13	 *
14	 * The run carries on. Stopping would not close a guard that has stopped guarding --
15	 * it would only remove the agent's ability to repair the configuration, leaving a
16	 * person to do it by hand. So the defect is reported and the run continues, and
17	 * something has to read the line afterwards. That is this.
18	 *
19	 * ## Why the fields and not the sentence
20	 *
21	 * The fields are the contract; the English beside them is not. A caller that greps
22	 * the prose is a caller whose tooling atoma breaks by rewording a warning. So this
23	 * reads `kind=`, `severity=` and the fields beside them, and never the sentence.
24	 *
25	 * ## Why one issue per finding, deduplicated
26	 *
27	 * A defect in the tools file is not transient: every run until somebody fixes it
28	 * reports the same line. Opening an issue per run would bury the repository in
29	 * duplicates, and opening one per finding would lose the second defect behind the
30	 * first. So the finding's own fields are hashed into a marker, and an OPEN issue
31	 * carrying that marker is left alone. A closed one is not -- the defect came back,
32	 * and that is worth saying again.
33	 *
34	 * Usage:
35	 *   report_config_findings.ts --repo OWNER/REPO --logs-file FILE --agent NAME
36	 */
37	import { existsSync, readFileSync } from "node:fs";
38	import { parseArgs } from "node:util";
39	import { gh } from "../../adapters/github/gh.ts";
40	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
41	import { defineScript } from "./lib/script-ref.ts";
42	
43	export interface ReportConfigFindingsArgs {
44	  repo: string;
45	  "logs-file": string;
46	  /** The agent to start on the issue, from `agents.on_config_finding`. */
47	  agent: string;
48	}
49	
50	export const ref = defineScript<ReportConfigFindingsArgs>(import.meta.url);
51	
52	/** The token a caller greps for. A constant in the core, and the same string here. */
53	const FINDING_PREFIX = "ATOMA_CONFIG_FINDING:";
54	
55	/**
56	 * The marker that makes an issue findable, and the hash that makes it unique.
57	 *
58	 * A comment rather than a label: labels are a project's to name and a marker is
59	 * not, and a search for a comment body needs no label to exist first. The hash is
60	 * over the finding's own fields, so the same defect in the same place is one issue
61	 * and a different defect is another.
62	 */
63	export function findingMarker(fields: string): string {
64	  const hash = new Bun.CryptoHasher("sha256").update(fields).digest("hex").slice(0, 16);
65	  return `<!-- atomaton:config-finding=${hash} -->`;
66	}
67	
68	/**
69	 * Every finding in the log, as its field string.
70	 *
71	 * One line per finding, and the fields are everything after the prefix. Kept as the
72	 * raw field string rather than parsed into a shape: this module's job is to
73	 * recognise and deduplicate, and a parser here would be a second reader of a format
74	 * the core owns -- one that goes stale the moment a field is added.
75	 */
76	export function findingsIn(log: string): string[] {
77	  const found: string[] = [];
78	  for (const line of log.split("\n")) {
79	    const at = line.indexOf(FINDING_PREFIX);
80	    if (at === -1) continue;
81	    const fields = line.slice(at + FINDING_PREFIX.length).trim();
82	    if (fields) found.push(fields);
83	  }
84	  // Deduplicated within one run: the same defect reported by two servers, or by the
85	  // same server twice, is one thing to fix.
86	  return [...new Set(found)];
87	}
88	
89	/** The issue title, from the fields. Short, and it names the kind and the subject. */
90	export function findingTitle(fields: string): string {
91	  const kind = /kind=(\S+)/.exec(fields)?.[1] ?? "unknown";
92	  const subject = /(?:server|tool)=(\S+)/.exec(fields)?.[1] ?? "";
93	  return subject ? `Config finding: ${kind} (${subject})` : `Config finding: ${kind}`;
94	}
95	
96	function log(message: string): void {
97	  console.error(`[config-findings] ${message}`);
98	}
99	
100	function main(): void {
101	  const { values } = parseArgs({
102	    args: Bun.argv.slice(2),
103	    options: {
104	      repo: { type: "string" },
105	      "logs-file": { type: "string" },
106	      agent: { type: "string" },
