23	/**
24	 * The line the command must be on: the first one that shows up when the issue is
25	 * read.
26	 *
27	 * Blank lines and HTML comments are skipped because neither is visible on the
28	 * rendered issue, so requiring the command literally first would fail on a body
29	 * that looks exactly right. Atomaton writes such comments itself — the
30	 * `atomaton:notify` tag `create_sub_issue` prefixes a body with is one — and an issue
31	 * that carried one silently started nothing.
32	 *
33	 * Nothing else is skipped in PROSE. A command below a paragraph of prose is not a command
34	 * at the top, and reading further would turn any mention of `/engineer` in a
35	 * discussion into a dispatch.
36	 *
37	 * Fenced code is skipped too (#311), for the opposite reason: it is perfectly visible.
38	 * A `/engineer` inside a code block is somebody quoting the format, not making a
39	 * request, and the thread readers do not take it for one. `proseOnly` blanks the
40	 * fences, so the line this returns is the body's first line of prose, and the entry
41	 * and the thread answer "is this a command" the same way about the same body.
42	 */
43	function commandLine(body: string): string {
44	  for (const raw of body.split("\n")) {
45	    const line = raw.trim();
46	    if (!line) continue;
47	    if (line.startsWith("<!--") && line.endsWith("-->")) continue;
48	    return line;
49	  }
50	  return "";
51	}
